import { useEffect, useState } from "react";
import "./UserDashboard.css";

function UserDashboard() {
  const [postings, setPostings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const loadPostings = async () => {
      try {
        const response = await fetch(
          `${process.env.REACT_APP_API_URL}/postings`,
        );

        if (!response.ok) {
          throw new Error("Failed to load postings");
        }

        const data = await response.json();
        setPostings(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    loadPostings();
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("jobmanager_user");
    window.location.href = "/login";
  };

  const currentUser = JSON.parse(
    localStorage.getItem("jobmanager_user") || "null"
  );
  const userName = currentUser?.email?.split("@")[0] || "User";

  return (
    <div className="user-dashboard-page">
      <div className="user-dashboard-container">
        <div className="user-dashboard-header">
          <h1>Welcome {userName}</h1>
          <button
            type="button"
            className="logout-button-small"
            onClick={handleLogout}
          >
            Logout
          </button>
        </div>

        {loading && (
          <p className="user-dashboard-loading">Loading postings...</p>
        )}
        {error && <p className="user-dashboard-error">{error}</p>}
        {!loading && !error && postings.length === 0 && (
          <p className="user-dashboard-empty">No postings available.</p>
        )}
        {!loading && !error && postings.length > 0 && (
          <ul className="user-dashboard-list">
            {postings.map((posting) => (
              <li key={posting.postingid} className="user-dashboard-item">
                <strong>{posting.company}</strong>
                <span>{posting.position}</span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default UserDashboard;
